<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait ClientIdentityUserAccessor
{
    private ClientIdentityUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): ClientIdentityUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(ClientIdentityUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = ClientIdentityUserVO::from($user);
        return $copy;
    }
}
